  "knowledge": "Community Resources",
  "description": "Illustrates the value of community resource availability.",
  "definition": "Ranges from Limited to Comprehensive. Limited indicates few or no resources, Adequate indicates sufficient resources, and Comprehensive indicates extensive resources."
}

{
  "id": 26,
  "knowledge": "Treatment Adherence",
  "description": "Illustrates the value of treatment adherence levels.",
  "definition": "Ranges from Non-compliant to High. Non-compliant indicates no adherence, Low indicates occasional adherence, Medium indicates regular adherence, and High indicates consistent adherence."
}

{
  "id": 60,
  "knowledge": "Correlation Between Resource Adequacy and Adherence (CRAA)",
  "description": "Measures the correlation between individual facility resource adequacy scores and treatment adherence rates.",
  "definition": "CRAA = \\text{CORR}(resource\\_score, tar), \\text{where } resource\\_score \\text{ is the facility's resource adequacy score, and } tar \\text{ is the treatment adherence rate for the facility.}"
}

{
  "id": 35,
  "knowledge": "Socio-Environmental Support Index (SESI)",
  "description": "Computes a composite index reflecting the quality of the patient's social environment and the facility's resource context.",
  "definition": "SESI = \\frac{SSE_{avg} + FRAI}{2}, \\text{combining average Social Support Effectiveness (SSE) across patients with Facility Resource Adequacy Index (FRAI)}"
}

{
  "id": 28,
  "knowledge": "Social Support Level",
  "description": "Illustrates the value of social support levels.",
  "definition": "Ranges from Limited to Strong. Limited indicates minimal support, Moderate indicates some support, and Strong indicates robust support."
}

{
  "id": 39,
  "knowledge": "Support System Pressure Index (SSPI)",
  "description": "Index assessing the pressure on support systems based on crisis frequency relative to social support effectiveness.",
  "definition": "SSPI = \\frac{CIF}{SSE_{avg} + 1}, \\text{calculating Crisis Intervention Frequency (CIF) relative to average Social Support Effectiveness (SSE) (adding 1 to avoid division by zero)}"
}

