{
  "id": 61,
  "knowledge": "Facility Performance Quadrant (FPQ)",
  "description": "Categorizes facilities into performance quadrants based on their Treatment Adherence Rate and Patient Stability Metric relative to median thresholds.",
  "definition": "A facility is assigned to one of four quadrants: 'High Adherence, High Stability' if TAR \u2265 median_tar and PSM \u2265 median_psm; 'High Adherence, Low Stability' if TAR \u2265 median_tar and PSM < median_psm; 'Low Adherence, High Stability' if TAR < median_tar and PSM \u2265 median_psm; 'Low Adherence, Low Stability' if TAR < median_tar and PSM < median_psm."
}

{
  "id": 34,
  "knowledge": "Resource-Demand Differential (RDD)",
  "description": "Measures the potential gap between average patient functional needs and available facility resources.",
  "definition": "RDD = PFIS - FRAI, \\text{comparing Patient Functional Impairment Score (PFIS) to Facility Resource Adequacy Index (FRAI)}"
}

{
  "id": 32,
  "knowledge": "Facility Risk Profile Index (FRPI)",
  "description": "Generates an index indicating the overall risk level associated with the patient population at a facility.",
  "definition": "FRPI = (\\frac{SRP}{100} \\times 5) + PFIS, \\text{weighting Suicide Risk Prevalence (SRP) and combining with Patient Functional Impairment Score (PFIS)}"
}

{
  "id": 15,
  "knowledge": "Resource-Supported Facility",
  "description": "Identifies facilities with adequate or comprehensive community resources.",
  "definition": "A facility with resource_score \\geq 2 \\text{where } resource_score = \\begin{cases} 3 & \\text{if } support\\_and\\_resources['community\\_resources'] = Comprehensive \\\\ 2 & \\text{if } support\\_and\\_resources['community\\_resources'] = Adequate \\\\ 1 & \\text{if } support\\_and\\_resources['community\\_resources'] = Limited \\end{cases}."
}
